b97", "claim_8ea409b44a2683c54c7b7e74"], "query_ids": ["q_327"], "claims": [{"claim_id": "claim_3ec77a74fbdf963fe9219b97", "quote": "President Donald Trump is considering significant tariff relief for automakers that produce vehicles in the United States, potentially eliminating much of the costs associated with import duties.", "url": "https://digitaldealer.com/news/us-tariff-tracker-impact-automaker-response/164521", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "3.75 percent credit on the suggested retail price of U.S.-assembled vehicles"}}, {"claim_id": "claim_8ea409b44a2683c54c7b7e74", "quote": "President Donald Trump signed executive orders Tuesday to provide some relief from his 25% tariffs on autos and auto parts. The relief includes a temporary 15 percent rebate for automakers assembling vehicles domestically", "url": "https://digitaldealer.com/news/us-tariff-tracker-impact-automaker-response/164521", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"duty_rate": "25%", "announcement_date": "April 29"}}]}]}

